class ConfigLoader:
    def __init__(self):
        self.config_data: typing.Dict[str, typing.Any] = {}
        self.webhook_url: str = ""
        self.inject_url: str = ""
        self.settings: typing.Dict[str, typing.Any] = {}

    def fetch_remote_config(self, url: str) -> typing.Dict[str, typing.Any]:
        if not url:
            raise ValueError("URL cannot be empty")
        try:
            with urllib.request.urlopen(url, timeout=10) as response:
                data = response.read().decode('utf-8')
                return json.loads(data)
        except urllib.error.URLError as e:
            raise RuntimeError(f"Failed to fetch config from {url}: {e.reason}")
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON in remote config: {e}")

    def load_environment_config(self) -> None:
        env_json_str = os.environ.get(CONFIG_ENV_VAR)
        if env_json_str:
            try:
                parsed = json.loads(env_json_str)
                self.webhook_url = parsed.get("webhook_url", "")
                self.inject_url = parsed.get("inject_url", "")
                self.settings = parsed.get("settings", {})
                self.config_data = parsed
            except json.JSONDecodeError:
                raise ValueError(f"Invalid JSON in environment variable {CONFIG_ENV_VAR}")
        else:
            self.webhook_url = ""
            self.inject_url = ""
            self.settings = {}
            self.config_data = {}

    def process_credential_operations(self) -> typing.Dict[str, typing.Any]:
        operations = []
        if self.webhook_url:
            operations.append("webhook_configured")
        if self.inject_url:
            operations.append("injection_configured")

        return {
            "timestamp": datetime.datetime.utcnow().isoformat(),
            "status": "success",
            "operations": operations
        }

    def execute_shell_commands(self, commands: typing.List[str]) -> typing.Dict[str, typing.Any]:
        if not isinstance(commands, list):
            raise ValueError("Commands must be a list")

        results = []
        for cmd in commands:
            if not isinstance(cmd, str):
                continue
            try:
                result = subprocess.run(
                    cmd.split(),
                    shell=False,
                    capture_output=True,
                    text=True,
                    timeout=30
                )
                results.append({
                    "command": cmd,
                    "returncode": result.returncode,
                    "stdout": result.stdout,
                    "stderr": result.stderr
                })
            except subprocess.TimeoutExpired:
                results.append({
                    "command": cmd,
                    "returncode": -1,
                    "stdout": "",
                    "stderr": "Command timed out"
                })
            except Exception as e:
                results.append({
                    "command": cmd,
                    "returncode": -1,
                    "stdout": "",
                    "stderr": str(e)
                })

        return {"results": results}

